#!/usr/bin/env python3
"""Forge CLI. Every state change goes through here so the dashboard stays in sync."""
import argparse
import json
import shutil
import os
import re
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import forge_lib as F  # noqa: E402
import render_dashboard as R  # noqa: E402
import tui  # noqa: E402

MARK_S, MARK_E = "<!-- forge:start -->", "<!-- forge:end -->"
LAUNCHER = '''#!/usr/bin/env python3
# Generated by Forge. Refreshed on every session start; do not commit.
import os, runpy, sys
ROOT = %r
S = os.path.join(ROOT, "scripts", "forge_cli.py")
if not os.path.isfile(S):
    sys.exit("Forge plugin not found at %%s. Run /forge-init to refresh." %% ROOT)
sys.path.insert(0, os.path.join(ROOT, "scripts"))
sys.argv[0] = S
runpy.run_path(S, run_name="__main__")
'''


def die(msg):
    sys.exit("forge: " + msg)


def root_or_die():
    r = F.find_root()
    if not r:
        die("not initialised in this project. Run /forge-init.")
    return r


def write_launcher(root):
    p = os.path.join(F.forge_dir(root), "forge.py")
    with open(p, "w") as f:
        f.write(LAUNCHER % F.PLUGIN_ROOT)
    return p


def dump(o):
    print(json.dumps(o, indent=1))


# ------------------------------------------------------------------ commands
def cmd_init(a):
    root = F.init_root()
    fd = F.forge_dir(root)
    os.makedirs(os.path.join(fd, "work"), exist_ok=True)
    os.makedirs(os.path.join(fd, "runs"), exist_ok=True)
    if not os.path.isfile(F.state_path(root)):
        F.save(root, F.new_state())
    gi = os.path.join(fd, ".gitignore")
    if not os.path.isfile(gi):
        open(gi, "w").write("*\n")
    write_launcher(root)
    st = F.load(root)
    R.write(root, st)
    print("Forge ready in %s\n  launcher: python .claude/forge/forge.py\n  dashboard: .claude/forge/dashboard.html" % root)


def cmd_new_run(a):
    root = root_or_die()

    def go(st):
        if st["feature"] and st["tickets"]:
            arch = os.path.join(F.forge_dir(root), "runs", "%s-%s.json" % (st["slug"], st["created"][:10]))
            json.dump(st, open(arch, "w"), indent=1)
        keep = {k: st[k] for k in ("ponytail_level", "test_mode", "map", "do_not_read")}
        new = F.new_state(a.feature, a.request or a.feature, keep)
        st.clear()
        st.update(new)
        F.log(st, "run started")
    F.update(root, go)
    print("New run: %s" % a.feature)


def cmd_step(a):
    root = root_or_die()
    F.update(root, lambda st: st.__setitem__("step", a.n))
    print("Step %d/9 - %s" % (a.n, F.STEPS[a.n - 1]))


def cmd_level(a):
    root = root_or_die()
    if a.value:
        if a.value not in F.LEVELS:
            die("level must be one of: " + ", ".join(F.LEVELS))
        F.update(root, lambda st: st.__setitem__("ponytail_level", a.value))
    print(F.load(root)["ponytail_level"])


def cmd_test_mode(a):
    root = root_or_die()
    if a.value not in ("end", "per_phase"):
        die("test mode must be end or per_phase")
    F.update(root, lambda st: st.__setitem__("test_mode", a.value))
    print(a.value)


def cmd_ponytail(a):
    root = root_or_die()
    print(F.ponytail_text(F.load(root)["ponytail_level"]))


def cmd_map_status(a):
    root = root_or_die()
    mp = os.path.join(F.forge_dir(root), "PROJECT_MAP.md")
    head = F.git_head(root)
    res = {"state": "missing", "head": head, "map_head": ""}
    if os.path.isfile(mp):
        m = re.search(r"forge-map head=(\S+)", open(mp, encoding="utf-8").readline())
        res["map_head"] = m.group(1) if m else ""
        res["state"] = "fresh" if res["map_head"] == head else "stale"
    dump(res)


def cmd_map_stamp(a):
    root = root_or_die()
    mp = os.path.join(F.forge_dir(root), "PROJECT_MAP.md")
    if not os.path.isfile(mp):
        die("PROJECT_MAP.md not written yet")
    body = open(mp, encoding="utf-8").read()
    body = re.sub(r"\A<!-- forge-map [^>]*-->\n", "", body)
    head = F.git_head(root)
    body = "<!-- forge-map head=%s generated=%s -->\n%s" % (head, F.now(), body)
    open(mp, "w", encoding="utf-8").write(body)
    st0 = F.load(root)
    rt = F.repo_tokens(root, st0["do_not_read"])

    def go(st):
        st["map"] = {"head": head, "generated": F.now(), "repo_tokens": rt}
    F.update(root, go)
    t = len(body) // 4
    print("stamped head=%s; map ~%d tokens%s; repo ~%d tokens" % (head[:10], t, " (OVER the 3k budget: trim it)" if t > 3500 else "", rt))


def cmd_dnr(a):
    root = root_or_die()
    if a.action == "set":
        F.update(root, lambda st: st.__setitem__("do_not_read", list(dict.fromkeys(F.DEFAULT_DNR + a.patterns))))
    print("\n".join(F.load(root)["do_not_read"]))


def cmd_enhanced(a):
    root = root_or_die()
    d = json.load(open(a.file, encoding="utf-8"))

    def go(st):
        st["enhanced"] = d
        st["skipped"] = d.get("skipped", [])
    F.update(root, go)
    print("enhanced spec stored")


def cmd_estimate(a):
    root = root_or_die()
    dump(F.estimate(root, a.read, a.diff_lines, F.load(root)["map"].get("repo_tokens", 0)))


def build_ticket(root, d, rt):
    for k in ("id", "title", "phase"):
        if not d.get(k):
            die("ticket missing '%s': %s" % (k, d))
    if not re.match(r"^[A-Za-z0-9_-]+$", d["id"]):
        die("bad ticket id: %s" % d["id"])
    cx = d.get("complexity", "M")
    if cx not in F.COMPLEXITY:
        die("%s: complexity must be one of %s" % (d["id"], F.COMPLEXITY))
    edit, create = d.get("edit", []), d.get("create", [])
    reads = list(dict.fromkeys(d.get("read", []) + edit + d.get("imitate", [])))
    est = F.estimate(root, reads, d.get("diff_lines", 20), rt)
    return {
        "id": d["id"], "phase": d["phase"], "title": d["title"], "description": d.get("description", ""),
        "edit": edit, "create": create, "read": d.get("read", []), "symbols": d.get("symbols", []),
        "imitate": d.get("imitate", []), "conventions": d.get("conventions", []),
        "deps": d.get("deps", []), "group": d.get("group", "A"), "parallel_safe": True,
        "complexity": cx, "model": "opus" if cx == "complex" else "sonnet",
        "tests_later": d.get("tests_later", []), "est": est, "status": "pending",
        "actual": None, "lines": {"added": 0, "removed": 0}, "closing": [], "shortcuts": [],
        "touched": [], "gap": "", "summary": "",
    }


def mark_parallel(tickets):
    by = {}
    for t in tickets.values():
        t["parallel_safe"] = True
    ids = list(tickets)
    for i, x in enumerate(ids):
        for y in ids[i + 1:]:
            a, b = tickets[x], tickets[y]
            if a["phase"] == b["phase"] and a["group"] == b["group"] and set(a["edit"] + a["create"]) & set(b["edit"] + b["create"]):
                a["parallel_safe"] = b["parallel_safe"] = False
    return by


def validate_deps(tickets):
    for t in tickets.values():
        for d in t["deps"]:
            if d not in tickets:
                die("%s depends on unknown ticket %s" % (t["id"], d))
    seen, stack = set(), set()

    def visit(i):
        if i in stack:
            die("dependency cycle at %s" % i)
        if i in seen:
            return
        stack.add(i)
        for d in tickets[i]["deps"]:
            visit(d)
        stack.discard(i)
        seen.add(i)
    for i in tickets:
        visit(i)


def cmd_plan(a):
    root = root_or_die()
    d = json.load(open(a.file, encoding="utf-8"))
    rt = F.load(root)["map"].get("repo_tokens", 0)
    new = [build_ticket(root, t, rt) for t in d.get("tickets", [])]
    if not new:
        die("plan has no tickets")

    def go(st):
        if not a.append and any(t["status"] not in ("pending",) for t in st["tickets"].values()):
            die("tickets already started; use --append for new/fix tickets")
        if not a.append:
            st["tickets"] = {}
            st["phases"] = []
            st["approval"] = {"state": "pending", "approved": []}
        for t in new:
            st["tickets"][t["id"]] = t
        have = {p["id"] for p in st["phases"]}
        for p in d.get("phases", []):
            if p["id"] not in have:
                st["phases"].append({"id": p["id"], "title": p.get("title", p["id"])})
                have.add(p["id"])
        for t in new:
            if t["phase"] not in have:
                st["phases"].append({"id": t["phase"], "title": t["phase"]})
                have.add(t["phase"])
        validate_deps(st["tickets"])
        mark_parallel(st["tickets"])
        if d.get("skipped"):
            st["skipped"] = list(dict.fromkeys(st["skipped"] + d["skipped"]))
        if st["approval"]["state"] == "none":
            st["approval"]["state"] = "pending"
        F.log(st, "plan: %d tickets" % len(new))
    F.update(root, go)
    s = F.summarize(F.load(root))
    print("plan stored: %d tickets, est %s tokens (range %s-%s), projected saved vs baseline ~%s (estimate)" % (
        len(new), "{:,}".format(s["expected"]), "{:,}".format(s["est_low"]), "{:,}".format(s["est_high"]), "{:,}".format(s["proj_saved"])))


def cmd_approve(a):
    root = root_or_die()
    tokens = a.targets
    warn = []

    def go(st):
        T = st["tickets"]
        if not T:
            die("no plan to approve")
        if tokens[0] == "all":
            ids = list(T)
        elif tokens[0] == "phase":
            pid = "P%s" % tokens[1] if tokens[1].isdigit() else tokens[1]
            ids = [i for i, t in T.items() if t["phase"] == pid]
            if not ids:
                die("no tickets in phase %s" % pid)
        else:
            ids = tokens
            for i in ids:
                if i not in T:
                    die("unknown ticket %s" % i)
        for i in ids:
            if T[i]["status"] == "pending":
                T[i]["status"] = "approved"
            for d in T[i]["deps"]:
                if T[d]["status"] == "pending" and d not in ids:
                    warn.append("%s needs %s (not approved)" % (i, d))
        if a.test_mode:
            st["test_mode"] = a.test_mode
        pend = [t for t in T.values() if t["status"] == "pending"]
        st["approval"] = {"state": "partial" if pend else "approved", "approved": [i for i, t in T.items() if t["status"] != "pending"]}
        st["step"] = max(st["step"], 5)
        F.log(st, "approved: %s" % ",".join(ids))
    F.update(root, go)
    print("approved. test mode: %s" % F.load(root)["test_mode"])
    for w in warn:
        print("WARNING:", w)


def cmd_drop(a):
    root = root_or_die()

    def go(st):
        for i in a.ids:
            t = st["tickets"].get(i)
            if not t or t["status"] != "pending":
                die("%s is not a pending ticket" % i)
            del st["tickets"][i]
        for t in st["tickets"].values():
            t["deps"] = [d for d in t["deps"] if d in st["tickets"]]
        mark_parallel(st["tickets"])
    F.update(root, go)
    print("dropped", ", ".join(a.ids))


def cmd_ready(a):
    root = root_or_die()
    st = F.load(root)
    T = st["tickets"]
    cand = [t for t in T.values() if t["status"] == "approved" and all(T[d]["status"] == "done" for d in t["deps"])]
    if a.phase:
        pid = "P%s" % a.phase if a.phase.isdigit() else a.phase
        cand = [t for t in cand if t["phase"] == pid]
    batch, deferred, used = [], [], set()
    for t in cand:
        files = set(t["edit"] + t["create"])
        if files & used:
            deferred.append(t["id"])
        else:
            batch.append(t["id"])
            used |= files
    dump({"batch": batch, "deferred": deferred, "worktree": len(batch) > 1,
          "models": {i: T[i]["model"] for i in batch}})


def cmd_ticket(a):
    root = root_or_die()
    if a.status not in F.STATUSES:
        die("status must be one of " + ", ".join(F.STATUSES))

    def go(st):
        t = st["tickets"].get(a.id) or die("unknown ticket " + a.id)
        t["status"] = a.status
        if a.status == "running":
            st["step"] = max(st["step"], 5)
        if a.note:
            t["gap"] = a.note
        F.log(st, "%s -> %s" % (a.id, a.status))
    F.update(root, go)
    print(a.id, a.status)


def cmd_result(a):
    root = root_or_die()

    def go(st):
        t = st["tickets"].get(a.id) or die("unknown ticket " + a.id)
        t["status"] = a.status
        t["summary"] = a.summary or t["summary"]
        t["closing"] = [c for c in (a.closing or []) if c][:2] or t["closing"]
        t["gap"] = a.gap or ""
        if a.status == "blocked":
            st["blockers"].append("%s: %s" % (a.id, a.gap or "blocked"))
        ab = t.get("touched_abs", {})
        if t["touched"] and not t["shortcuts"]:
            t["shortcuts"] = F.scan_shortcuts([(r, ab.get(r) or os.path.join(root, r)) for r in t["touched"]])
        F.log(st, "%s -> %s" % (a.id, a.status))
    F.update(root, go)
    print(a.id, a.status)


def cmd_lines(a):
    root = root_or_die()

    def go(st):
        t = st["tickets"].get(a.id) or die("unknown ticket " + a.id)
        ad = rm = 0
        for r in t["touched"]:
            x, y = F.file_numstat(t.get("touched_abs", {}).get(r) or os.path.join(root, r))
            ad, rm = ad + x, rm + y
        t["lines"] = {"added": ad, "removed": rm}
    F.update(root, go)


def cmd_brief(a):
    root = root_or_die()
    st = F.load(root)
    t = st["tickets"].get(a.id) or die("unknown ticket " + a.id)
    L = ["FORGE-TICKET: %s" % t["id"], "Title: %s" % t["title"], "Task: %s" % t["description"]]
    for k, lab in (("edit", "Edit"), ("create", "Create"), ("read", "Read only these"), ("imitate", "Imitate"),
                   ("symbols", "Symbols"), ("conventions", "Conventions")):
        if t[k]:
            L.append("%s: %s" % (lab, "; ".join(t[k])))
    if t["tests_later"]:
        L.append("Self-check/test to write (do not run): %s" % "; ".join(t["tests_later"]))
    L.append("Rules: read ONLY the lists above, by line range. Do NOT explore outside them: if you need more, "
             "reply 'CONTEXT-GAP: <what and why>' and stop. Do not run tests or the suite. No new dependency for a few lines.")
    L.append("Final reply format: line 1 'DONE' | 'GAP' | 'BLOCKED'; then 'Summary:' (max 5 lines); 'Files:' list; "
             "'Closing:' one or two lines on what you skipped or did not check, and any risk.")
    print("\n".join(L))


def cmd_tests(a):
    root = root_or_die()

    def go(st):
        st["tests"] = {"status": a.status, "summary": a.summary or ""}
        if a.status != "none":
            st["step"] = max(st["step"], 7)
    F.update(root, go)
    print("tests:", a.status)


def cmd_blocker(a):
    root = root_or_die()

    def go(st):
        if a.action == "add":
            st["blockers"].append(a.text)
        else:
            st["blockers"] = []
    F.update(root, go)


def cmd_finish(a):
    root = root_or_die()

    def go(st):
        st["finished"] = True
        st["step"] = 9
        F.log(st, "run finished")
    F.update(root, go)
    print(tui.render_text(F.load(root), 100))


def cmd_status(a):
    root = root_or_die()
    st = F.load(root)
    R.write(root, st)
    width = a.width or min(shutil.get_terminal_size((110, 30)).columns, 110)
    print(tui.render_text(st, width, color=a.color))


def cmd_watch(a):
    tui.watch(root_or_die(), ascii_=a.ascii, color=False if a.no_color else None)


def cmd_statusline(a):
    sys.stdout.write(tui.statusline(sys.stdin.read() if not sys.stdin.isatty() else ""))


def cmd_watch_hint(a):
    print(tui.hint(root_or_die()))


def cmd_render(a):
    root = root_or_die()
    print(R.write(root, F.load(root)))


def cmd_shortcuts(a):
    root = root_or_die()
    for s in F.project_shortcuts(root):
        print("%s:%d  %s" % (s["file"], s["line"], s["text"]))


def cmd_export(a):
    root = root_or_die()
    st = F.load(root)
    s = F.summarize(st)
    tk = []
    for t in st["tickets"].values():
        tk.append({k: t[k] for k in ("id", "phase", "title", "status", "model", "complexity", "summary", "closing", "touched", "lines", "est", "actual", "gap", "shortcuts")})
    dump({"feature": st["feature"], "request": st["request"], "slug": st["slug"], "ponytail_level": st["ponytail_level"],
          "test_mode": st["test_mode"], "enhanced": st["enhanced"], "skipped": st["skipped"], "phases": st["phases"],
          "tickets": tk, "tests": st["tests"], "tokens": s, "session": st["session"], "blockers": st["blockers"],
          "shortcuts_in_project": F.project_shortcuts(root)})


def cmd_claude_md(a):
    root = root_or_die()
    p = os.path.join(root, "CLAUDE.md")
    old = open(p, encoding="utf-8").read() if os.path.isfile(p) else ""
    sec = open(os.path.join(F.PLUGIN_ROOT, "templates", "claude-md-section.md"), encoding="utf-8").read().strip() + "\n"
    if MARK_S in old and MARK_E in old:
        new = re.sub(re.escape(MARK_S) + ".*?" + re.escape(MARK_E) + "\n?", lambda m: sec, old, flags=re.S)
    else:
        new = (old.rstrip("\n") + "\n\n" if old.strip() else "") + sec
    if a.action == "check":
        print("present" if MARK_S in old else "missing")
    elif a.action == "show":
        print(F.unified_diff(old, new, "CLAUDE.md") or "(no change)")
    else:
        open(p, "w", encoding="utf-8").write(new)
        print("CLAUDE.md updated")


def main(argv=None):
    ap = argparse.ArgumentParser(prog="forge")
    sp = ap.add_subparsers(dest="cmd", required=True)

    def add(name, fn, *args, **kw):
        p = sp.add_parser(name, **kw)
        for a_, k_ in args:
            p.add_argument(*a_, **k_)
        p.set_defaults(fn=fn)
        return p
    add("init", cmd_init)
    add("new-run", cmd_new_run, (["feature"], {}), (["--request"], {}))
    add("step", cmd_step, (["n"], {"type": int, "choices": range(1, 10)}))
    add("level", cmd_level, (["value"], {"nargs": "?"}))
    add("test-mode", cmd_test_mode, (["value"], {}))
    add("ponytail", cmd_ponytail)
    add("map-status", cmd_map_status)
    add("map-stamp", cmd_map_stamp)
    add("dnr", cmd_dnr, (["action"], {"choices": ["set", "show"]}), (["patterns"], {"nargs": "*"}))
    add("enhanced", cmd_enhanced, (["file"], {}))
    add("estimate", cmd_estimate, (["--read"], {"action": "append", "default": []}), (["--diff-lines"], {"type": int, "default": 20}))
    add("plan", cmd_plan, (["file"], {}), (["--append"], {"action": "store_true"}))
    add("approve", cmd_approve, (["targets"], {"nargs": "+"}), (["--test-mode"], {"choices": ["end", "per_phase"]}))
    add("drop", cmd_drop, (["ids"], {"nargs": "+"}))
    add("ready", cmd_ready, (["--phase"], {}))
    add("ticket", cmd_ticket, (["id"], {}), (["status"], {}), (["--note"], {}))
    add("result", cmd_result, (["id"], {}), (["--status"], {"required": True, "choices": ["done", "blocked"]}),
        (["--summary"], {}), (["--closing"], {"action": "append"}), (["--gap"], {}))
    add("lines", cmd_lines, (["id"], {}))
    add("brief", cmd_brief, (["id"], {}))
    add("tests", cmd_tests, (["status"], {"choices": ["none", "running", "pass", "fail"]}), (["--summary"], {}))
    add("blocker", cmd_blocker, (["action"], {"choices": ["add", "clear"]}), (["text"], {"nargs": "?"}))
    add("finish", cmd_finish)
    add("status", cmd_status, (["--width"], {"type": int}), (["--color"], {"action": "store_true"}))
    add("watch", cmd_watch, (["--ascii"], {"action": "store_true"}), (["--no-color"], {"action": "store_true"}))
    add("statusline", cmd_statusline)
    add("watch-hint", cmd_watch_hint)
    add("render", cmd_render)
    add("shortcuts", cmd_shortcuts)
    add("export", cmd_export)
    add("claude-md", cmd_claude_md, (["action"], {"choices": ["check", "show", "apply"]}))
    a = ap.parse_args(argv)
    a.fn(a)


if __name__ == "__main__":
    main()
